    files = json.loads(_curl(f"{base}/api/videofile.php?video_id={vid}&lifetime=8640000", referer=page))
    if not isinstance(files, list):
        raise RuntimeError("abtranny не отдал список файлов")
    prefer = ("_fhd.mp4", ".mp4", "_sd")
    if quality_label == "480p":
        prefer = (".mp4", "_sd", "_fhd.mp4")
    chosen = None
    for fmt in prefer:
        chosen = next((item for item in files if item.get("format") == fmt and item.get("video_url")), None)
        if chosen:
            break
    if not chosen:
